var socket = io()

socket.emit('save id', 'Controlpanel:')

$(document).ready(function () {
    $('#remote-display').attr('src', window.location.origin + '/remote?hostname=' + window.location.hostname)
    getAPILayout()
    getAPIText()
    getAPIMedia()
    gettextslot()
    getmediaslot()
    getmediafiles()
    setInterval(function () {
        deviceinfo()
    }, 5000)

})

$('#shutdown').click(function () {
    shutdown()
})

$('#reboot').click(function () {
    reboot()
})

$('#refresh').click(function () {
    refresh()
})

$('#restartapp').click(function () {
    restartapp()
})

$('.btnUpdateLyt').click(function () {
    var lytid = $('#updateLytInput').val()
    updateLyt(lytid)
})

$('.btnReplaceText').click(function () {
    var layoutid = $('#replaceTextList').find(":selected").attr('class')
    var textname = $('#replaceTextList').find(":selected").val()
    var textReplace = $('#replaceTextInput').val()
    replacetextslot(layoutid, textname, textReplace)
})

$('.btnReplaceMedia').click(function () {
    var layoutid = $('#replaceMediaList').find(":selected").attr('class')
    var textname = $('#replaceMediaList').find(":selected").val()
    var textReplace = $('#mediaFilesList').find(":selected").val()
    replacemediaslot(layoutid, textname, textReplace)
})

function updateLyt(id) {
    socket.emit('replace-layout', {
        id: id
    })
}

function getAPILayout() {
    var ipaddress = window.location.hostname
    $('#apiLayout').text('[GET] Eg : http://' + ipaddress + ':9000/api/update-layout?id=LAYOUT_ID')
}

function getAPIText() {
    var ipaddress = window.location.hostname
    $('#apiText').text('[GET] Eg : http://' + ipaddress + ':9000/api/replace-text?slotname=Title&text=Test')
}

function getAPIMedia() {
    var ipaddress = window.location.hostname
    $('#apiMedia').text('[GET] Eg : http://' + ipaddress + ':9000/api/replace-media?slotname=Title&filename=Test.png')
}

function gettextslot() {
    var checklayoutname = '&*&*&'
    socket.emit('reqtextslot', 'cpanel')
    socket.on('cpanel-textslot', function (textSlotlist) {
        $('#replaceTextList').html('')
        $('#replaceTextList').append('<option>Open this to select text slot. Slot Name | Slot Text</option>')
        textSlotlist.forEach(function (textslot, tindex) {
            var text = textslot.text
            text = text.length > 40 ? text.substring(0,40) : text
            if (textslot.layout != checklayoutname) {
                checklayoutname = textslot.layout
                $('#replaceTextList').append('<option class="layout-name" value="' + textslot.myid + '" disabled>Layout Name: ' + textslot.myid + ' | ' + textslot.layout + '</option>')
            }
            $('#replaceTextList').append('<option class="' + textslot.myid + '" value="' + textslot.slotname + '">\xA0\xA0\xA0\xA0\xA0\xA0' + textslot.slottype +
                ' : ' + textslot.slotname + ' \n\t \n\t\n\t \n\t| ' + text + '</option>')
        })
    })
}

function replacetextslot(layoutid, textname, textReplace) {
    socket.emit('replace-text', {
        layoutid: layoutid,
        slotname: textname,
        text: textReplace
    })
}

function getmediaslot() {
    socket.emit('reqmediaslot', 'cpanel')
    socket.on('cpanel-mediaslot', function (mediaSlotlist) {
        $('#replaceMediaList').html('')
        $('#replaceMediaList').append('<option>Open this to select media slot. Slot Name | Slot Text</option>')
        mediaSlotlist.forEach(function (mediaslot, tindex) {
            $('#replaceMediaList').append('<option class="layout-name" value="layout-' + mediaslot.myid + '" disabled>Layout Name: ' + mediaslot.myid + ' | ' + mediaslot.layout + '</option>')
            $('#replaceMediaList').append('<option class="' + mediaslot.myid + '" value="' + mediaslot.slotname + '">\xA0\xA0\xA0\xA0\xA0\xA0' +
                mediaslot.slotname + ' \n\t \n\t\n\t \n\t| ' + mediaslot.text + '</option>')
            if (tindex == mediaSlotlist.length - 1) {
                $("#replaceMediaList option:contains('Layout Name: " + mediaslot.myid + ' | ' + mediaslot.layout + "')").each(function (idx, val) {
                    if(idx != 0) {
                        $(this).remove()
                    }
                })
            }
        })
    })
}

function getmediafiles() {
    socket.emit('reqmediafiles', 'cpanel')
    socket.on('cpanel-mediafiles', function (mediaFileslist) {
        $('#mediaFilesList').html('')
        $('#mediaFilesList').append('<option>Open this to select media filename</option>')
        mediaFileslist.forEach(function (mediafiles, tindex) {
            $('#mediaFilesList').append('<option value="' + mediafiles + '">' +
                mediafiles + '</option>')
        })
    })
}

function replacemediaslot(layoutid, slotname, filenameReplace) {
    socket.emit('replace-media', {
        slotname: slotname,
        filename: filenameReplace
    })
}

function shutdown() {
    $.ajax({
        url: '/api/shutdown',
        type: 'GET',
        success: function (data) {
            console.log(data)
        },
        error: function (xhr, textStatus, errorThrown) {
            if (textStatus == 'timeout' || textStatus == 'error') {
                //console.log('warn', `Ajax error ${textStatus} ${errorThrown}`)
                return
            }
        }
    })
}

