function deviceinfo() {
    $.ajax({
        url: '/api/deviceinfo',
        type: 'GET',
        success: function (data) {
            if (JSON.parse(data)) {
                try {
                    var systeminfo = JSON.parse(data)
                    $('#sManu').text(systeminfo['manufacturer'])
                    $('#sBrand').text(systeminfo['brand'])
                    $('#sSpeed').text(systeminfo['speed'])
                    $('#sCores').text(systeminfo['cores'])
                    $('#sPhysicalCores').text(systeminfo['physicalCores'])
                } catch (e) {
                    return e
                }
            }
        },
        error: function (xhr, textStatus, errorThrown) {
            if (textStatus == 'timeout' || textStatus == 'error') {
                //console.log('warn', `Ajax error ${textStatus} ${errorThrown}`)
                return
            }
        }
    })
}